using System;using System.IO;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Automation;using System.Windows.Threading;
namespace SeraphimLuxury {
 partial class MainWindow {
  internal void VerifySurface16(){if(navigation.Count!=4||String.Join(",",navigation.Select(b=>(string)b.Tag))!="Accueil,Applications,Planning,Atlas")throw new Exception("Quatre pages, Atlas en dernier");if(greeting14==null||!greeting14.Text.Contains("vous")||!greeting14.Text.Contains("Welcome"))throw new Exception("Accueil personnalisé");}
 }
 static class Refinement16Tests {
  static void Check(bool value,string name){if(!value)throw new Exception(name);}
  public static int Run(string dir){Directory.CreateDirectory(dir);var app=new Application {ShutdownMode=ShutdownMode.OnExplicitShutdown};var prefs=Preferences.Defaults();prefs.Premium=true;prefs.ReducedMotion=true;var store=new PreferenceStore(Path.Combine(dir,"preferences.json"));store.Save(prefs);var w=new MainWindow(store,true){Opacity=0,ShowInTaskbar=false};app.MainWindow=w;int stage=0;double position=0;var timer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(700)};timer.Tick+=delegate{try{switch(stage++){
   case 0:w.VerifySurface16();w.Capture(Path.Combine(dir,"home.png"));w.atlas.Seek(0);Check(w.shownChapter!=null&&w.shownChapter.year==0,"Nativité sur la frise mondiale");w.Capture(Path.Combine(dir,"nativity.png"));w.atlas.Seek(AtlasPlaces.PositionOf(1989));Check(w.shownChapter!=null&&w.shownChapter.title.Contains("Web"),"Web documenté sur la frise");position=w.atlas.Position;break;
   case 1:Check(w.atlas.Position==position&&!w.atlas.Playing,"Pas de défilement du temps dans la vue mondiale");w.atlas.BeginPan(new Point(300,250));w.atlas.MovePan(new Point(380,280));w.atlas.EndPan();Check(Math.Abs(w.atlas.CameraSnapshot()[1])>20,"Déplacement sans zoom");w.atlas.RestoreCamera(new[]{5.0,-2000.0,-950.0});w.Capture(Path.Combine(dir,"map-pan.png"));w.atlas.SetGlobe(true);for(int i=0;i<12;i++)w.atlas.ZoomAt(new Point(500,250),1.5);Check(w.atlas.GlobeScale>8,"Zoom pays sur le globe");w.atlas.SelectCity(AtlasPlaces.Data.cities.First(c=>c.id=="FRA-paris"),true);w.Capture(Path.Combine(dir,"globe-zoom.png"));w.ToggleAtlasFullScreen();Check(w.atlasImmersion!=null,"Atlas plein écran");w.ToggleAtlasFullScreen();w.ShowPage("Applications");break;
   case 2:w.Capture(Path.Combine(dir,"applications.png"));int builds=w.ApplicationPageBuilds14;var target=ToolsTests.Descend(w.ToolsPage).OfType<Button>().First(b=>AutomationProperties.GetName(b)=="Choisir Instagram");target.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(w.ApplicationPageBuilds14==builds,"Sélection sans reconstruire l’application");w.Width=980;w.Height=680;w.Capture(Path.Combine(dir,"applications-minimum.png"));w.ShowPage("Planning");break;
   case 3:w.Capture(Path.Combine(dir,"planning-minimum.png"));File.WriteAllText(Path.Combine(dir,"report.txt"),"PASS quatre pages, prénom et accueil, frise mondiale 0/1989, temps stable, déplacement sans zoom, globe >8x, plein écran, sélection locale, captures 980x680.");timer.Stop();w.Close();app.Shutdown();break;
  }}catch(Exception ex){timer.Stop();File.WriteAllText(Path.Combine(dir,"report.txt"),"FAIL stage "+stage+" "+ex);w.Close();app.Shutdown(1);}};w.Loaded+=delegate{timer.Start();};return app.Run(w);}
 }
}
